const categorySlug: Record<CharacterCategory, string> = {
  Cinematic: "cinematic",
  Fantasy: "fantasy",
  Anime: "anime",
  "3D avatars": "3d-avatars",
  Vintage: "vintage",
  Painting: "painting",
  "Professional portraits": "professional-portraits",
};

function inputRoles(count: 1 | 2): string[] {
  return count === 2 ? ["first photo", "second photo"] : ["source photo"];
}

/**
 * Standalone character action styles 147–222 (superhero, anime, game, fantasy,
 * sci-fi, film poster, collectible toy, cinematic fashion). No guide page.
 * Two-photo couple styles store Photo 2 as source-<n>b.webp on a second
 * example pair that shares result-<n>.webp.
 */
export const seedCharacterStyles: CatalogStyle[] = characters.map((item, index) => {
  const source = asset(`source-${item.n}.png`);
  const result = asset(`result-${item.n}.png`);
  const pixels = { resultWidth: item.resultWidth, resultHeight: item.resultHeight };
  const examplePairs: CatalogStyle["examplePairs"] = [
    {
      source,
      result,
      altSource: item.altSource,
      altResult: item.altResult,
      ...pixels,
    },
  ];
  if (item.inputImageCount === 2 && item.altSecond) {
    examplePairs.push({
      source: asset(`source-${item.n}b.png`),
      result,
      altSource: item.altSecond,
      altResult: item.altResult,
      ...pixels,
    });
  }
  return {
    id: item.id,
    title: item.title,
    category: item.category,
    subject: item.subject,
    intent: item.intent,
    requirement: item.requirement,
    tool: "Gemini",
    note: item.note,
    height: item.height,
    saved: 80 - index,
    source,
    result,
    status: "published",
    targetSourcePhoto: item.targetSourcePhoto,
    description: item.description,
    bestSourcePhoto: item.bestSourcePhoto,
    changes: item.changes,
    stays: item.stays,
    examplePairs,
    promptVariant: {
      id: `${item.id}-v1`,
      version: "1.0.0",
      tool: "Gemini",
      mode: "Image edit / transform with uploaded photo",
      inputImageCount: item.inputImageCount,
      inputImageRoles: inputRoles(item.inputImageCount),
      template: item.template,
      defaults: {
        mood: item.mood,
        background: item.background,
        ratio: item.ratio,
        keepClothing: item.keepClothing,
        keepPose: item.keepPose,
      },
      lastVerified: "",
      limitations: [aiGeneratedLimit, faceOcclusionLimit],
    },
  };
});

export const characterStyleIds = new Set(seedCharacterStyles.map((style) => style.id));

export const characterCategorySlug = categorySlug;

/** Publish payload kept beside the seed; scripts/publish-character-standalone.mjs embeds the same data. */
export const characterPublishRows = characters.map((item, index) => ({
  n: item.n,
  id: item.id,
  title: item.title,
  note: item.note,
  description: item.description,
  categorySlug: categorySlug[item.category],
  subject: item.subject,
  intent: item.intent,
  requirement: item.requirement,
  tool: "Gemini",
  height: item.height,
  saved: 80 - index,
  status: "published" as const,
  targetSourcePhoto: item.targetSourcePhoto,
  bestSourcePhoto: item.bestSourcePhoto,
  changes: item.changes,
  stays: item.stays,
  beforeFile: item.beforeFile,
  afterFile: item.afterFile,
  ...(item.beforeBFile ? { beforeBFile: item.beforeBFile } : {}),
  altSource: item.altSource,
  altResult: item.altResult,
  ...(item.altSecond ? { altSecond: item.altSecond } : {}),
  resultWidth: item.resultWidth,
  resultHeight: item.resultHeight,
  variant: {
    id: `${item.id}-v1`,
    tool: "Gemini",
    mode: "Image edit / transform with uploaded photo",
    inputImageCount: item.inputImageCount,
    inputImageRoles: inputRoles(item.inputImageCount),
    version: "1.0.0",
    template: item.template,
    defaults: {
      mood: item.mood,
      background: item.background,
      ratio: item.ratio,
      keepClothing: item.keepClothing,
      keepPose: item.keepPose,
    },
    limitations: [aiGeneratedLimit, faceOcclusionLimit],
  },
}));

